import type { Migration } from "./migrate";

/** Source of `.space/migrations.ts`: every migration's SQL, inlined in order. */
export function generateMigrationsSource(migrations: Migration[]): string {
	const entries = migrations.map(
		(migration) =>
			`\t{ id: ${JSON.stringify(migration.id)}, sql: ${JSON.stringify(migration.sql)} },`,
	);
	return [
		"// Generated by space. Do not edit.",
		'import type { Migration } from "spacefn/db";',
		"",
		"export const migrations: Migration[] = [",
		...entries,
		"];",
		"",
	].join("\n");
}
